// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }
    function testRegression_property() public {
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.seedMarket{value: 1 ether}(1000);

        vm.prank(address(0x2));
        c.getFreeKilo();

        vm.prank(address(0x2));
        c.collectDrugs(address(0));

        vm.warp(block.timestamp + 1);

        vm.prank(address(0x2));
        c.collectDrugs(address(0));
        vm.warp(1000000);
        vm.prank(address(0x2));
        c.collectDrugs(address(0));
        assertTrue(c.lastCollect(address(0x2)) == 1000000);
    }
}
